#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_compact_calloc_failure(void) {
    // Setup: create a buffer with some data
    buffer_t *buf = buffer_new_with_copy("abcdef");
    TEST_ASSERT_NOT_NULL(buf);

    // Simulate calloc failure on the allocation inside buffer_compact
    // buffer_new_with_copy: 2 allocations (struct + data)
    // buffer_compact: next allocation (calloc) should fail
    malloc_fail_after(2);

    // Test: call buffer_compact, which should fail due to calloc returning NULL
    ssize_t result = buffer_compact(buf);

    // Assert: should return -1 on allocation failure
    TEST_ASSERT_EQUAL_INT(-1, result);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_compact_calloc_failure);
    return UNITY_END();
}


